// Suite: generate_ids

test('generate_ids_generates_monotonically_increasing_ids', async (client) => {
  const ids: bigint[] = []
  for (let index = 0; index < 100000; index++) {
    if (index % 10000 === 0) {
      await sleep_ms(1)
    }
    ids.push(id())
  }
  for (let i = 1; i < ids.length; i++) {
    assert.ok(ids[i - 1] < ids[i])
  }
})

