// Suite: close_client

test('close_client_fails_operations_after_close', async (client) => {
  client.destroy()
  await assert.rejects(async (): Promise<void> => {
    await client.lookupAccounts([id()])
  }, (error: unknown): boolean => {
    assert.ok(error instanceof RequestError)
    assert.strictEqual(error.code, ErrorCodes.ERR_CLIENT_CLOSED)
    return true
  })
})

test('close_client_ignores_a_second_close', async (client) => {
  client.destroy()
  client.destroy()
})

async function main () {
  const start = new Date().getTime()
  for (let i = 0; i < tests.length; i++) {
    const client = createClient({
      cluster_id: 0n,
      replica_addresses: REPLICA_ADDRESSES,
    })
    try {
      await tests[i].fn(client).then(() => {
        console.log(tests[i].name + ": PASSED")
      }).catch(error => {
        console.log(tests[i].name + ": FAILED")
        throw error
      })
    } finally {
      client.destroy()
    }
  }
  const end = new Date().getTime()
  console.log('Time taken (s):', (end - start)/1000)
}

main().catch((error: AssertionError) => {
  console.log('operator:', error.operator)
  console.log('stack:', error.stack)
  process.exit(-1);
})
